import { describe, expect, it } from 'bun:test';
import { z } from 'zod';
import type { Task } from '../../src/core/types.js';
import type { LanePoolOptions, LanePoolResult, StepDefinition, StepResult } from '../../src/pool/types.js';
import { TaskTracker } from '../../src/tracking/task-status.js';

// ─── StepDefinition ─────────────────────────────────────────────────────────

describe('StepDefinition', () => {
  it('serializes and round-trips with required fields only', () => {
    const step: StepDefinition = {
      name: 'implement',
      profileId: 'coder',
      isReadOnly: false,
    };

    const json = JSON.stringify(step);
    const parsed = JSON.parse(json) as StepDefinition;

    expect(parsed.name).toBe('implement');
    expect(parsed.profileId).toBe('coder');
    expect(parsed.isReadOnly).toBe(false);
    expect(parsed.schema).toBeUndefined();
    expect(parsed.isApproved).toBeUndefined();
    expect(parsed.getFeedback).toBeUndefined();
  });

  it('serializes and round-trips with optional schema-driven fields', () => {
    const reviewSchema = z.object({
      approved: z.boolean(),
      feedback: z.string().optional(),
    });

    const step: StepDefinition<z.infer<typeof reviewSchema>> = {
      name: 'review',
      profileId: 'reviewer',
      isReadOnly: true,
      schema: reviewSchema,
      isApproved: (result) => result.approved === true,
      getFeedback: (result) => result.feedback ?? 'No feedback provided',
    };

    const json = JSON.stringify({
      name: step.name,
      profileId: step.profileId,
      isReadOnly: step.isReadOnly,
    });
    const parsed = JSON.parse(json) as StepDefinition;

    expect(parsed.name).toBe('review');
    expect(parsed.profileId).toBe('reviewer');
    expect(parsed.isReadOnly).toBe(true);
  });

  it('isApproved function correctly evaluates approval', () => {
    const schema = z.object({ approved: z.boolean(), feedback: z.string().optional() });

    const step: StepDefinition<z.infer<typeof schema>> = {
      name: 'review',
      profileId: 'reviewer',
      isReadOnly: true,
      schema,
      isApproved: (result) => result.approved === true,
    };

    expect(step.isApproved!({ approved: true, feedback: undefined })).toBe(true);
    expect(step.isApproved!({ approved: false, feedback: 'bad' })).toBe(false);
  });

  it('getFeedback function extracts feedback with fallback', () => {
    const schema = z.object({ approved: z.boolean(), feedback: z.string().optional() });

    const step: StepDefinition<z.infer<typeof schema>> = {
      name: 'review',
      profileId: 'reviewer',
      isReadOnly: true,
      schema,
      getFeedback: (result) => result.feedback ?? 'No feedback provided',
    };

    expect(step.getFeedback!({ approved: false, feedback: 'Missing tests' })).toBe('Missing tests');
    expect(step.getFeedback!({ approved: false, feedback: undefined })).toBe('No feedback provided');
  });

  it('isReadOnly distinguishes read-only from writable steps', () => {
    const readOnly: StepDefinition = { name: 'review', profileId: 'reviewer', isReadOnly: true };
    const writable: StepDefinition = { name: 'implement', profileId: 'coder', isReadOnly: false };

    expect(readOnly.isReadOnly).toBe(true);
    expect(writable.isReadOnly).toBe(false);
    expect(readOnly.isReadOnly).not.toBe(writable.isReadOnly);
  });
});

// ─── StepResult ─────────────────────────────────────────────────────────────

describe('StepResult', () => {
  it('approved variant narrows correctly in if-statement', () => {
    const result: StepResult = {
      type: 'approved',
      output: { filesChanged: 3 },
    };

    if (result.type === 'approved') {
      expect(result.output).toEqual({ filesChanged: 3 });
    } else {
      expect.unreachable('Should have narrowed to approved');
    }
  });

  it('rejected variant narrows correctly in if-statement', () => {
    const result: StepResult = {
      type: 'rejected',
      feedback: 'Missing test coverage',
    };

    if (result.type === 'rejected') {
      expect(result.feedback).toBe('Missing test coverage');
    } else {
      expect.unreachable('Should have narrowed to rejected');
    }
  });

  it('approved and rejected are distinguishable by type', () => {
    const results: StepResult[] = [
      { type: 'approved', output: null },
      { type: 'rejected', feedback: 'error' },
      { type: 'approved', output: { score: 95 } },
    ];

    const approved = results.filter((r) => r.type === 'approved');
    const rejected = results.filter((r) => r.type === 'rejected');

    expect(approved).toHaveLength(2);
    expect(rejected).toHaveLength(1);
  });

  it('output can hold arbitrary structured data', () => {
    const result: StepResult = {
      type: 'approved',
      output: { nested: { deep: [1, 2, 3] } },
    };

    if (result.type === 'approved') {
      expect((result.output as { nested: { deep: number[] } }).nested.deep).toEqual([1, 2, 3]);
    }
  });
});

// ─── LanePoolResult ─────────────────────────────────────────────────────────

describe('LanePoolResult', () => {
  it('calculates total tasks from completed and failed counts', () => {
    const result: LanePoolResult = { completedTasks: 7, failedTasks: 2 };

    const total = result.completedTasks + result.failedTasks;
    expect(total).toBe(9);
  });

  it('handles all-success scenario', () => {
    const result: LanePoolResult = { completedTasks: 10, failedTasks: 0 };

    expect(result.completedTasks).toBe(10);
    expect(result.failedTasks).toBe(0);
    expect(result.completedTasks + result.failedTasks).toBe(10);
  });

  it('handles all-failure scenario', () => {
    const result: LanePoolResult = { completedTasks: 0, failedTasks: 5 };

    expect(result.completedTasks).toBe(0);
    expect(result.failedTasks).toBe(5);
    expect(result.completedTasks + result.failedTasks).toBe(5);
  });

  it('serializes to JSON correctly', () => {
    const result: LanePoolResult = { completedTasks: 3, failedTasks: 1 };
    const json = JSON.stringify(result);
    const parsed = JSON.parse(json) as LanePoolResult;

    expect(parsed.completedTasks).toBe(3);
    expect(parsed.failedTasks).toBe(1);
  });
});

// ─── getStepsForTask with TaskTracker integration ───────────────────────────

describe('getStepsForTask with TaskTracker', () => {
  it('returns steps that match the task profile', () => {
    const tracker = new TaskTracker();
    tracker.addTask({
      id: 't1',
      title: 'Implement feature',
      prompt: 'Add login page',
      profile: 'coder',
      files: ['src/login.ts'],
      dependencies: [],
    });

    const task = tracker.getTask('t1')!;
    expect(task).toBeDefined();
    expect(task.status).toBe('ready');

    const getStepsForTask = (t: Task): StepDefinition[] => [
      { name: 'scout', profileId: 'scout', isReadOnly: true },
      { name: 'implement', profileId: t.profile, isReadOnly: false },
      { name: 'review', profileId: 'reviewer', isReadOnly: true },
    ];

    const steps = getStepsForTask(task);
    expect(steps).toHaveLength(3);
    expect(steps[1].profileId).toBe(task.profile);
    expect(steps[1].profileId).toBe('coder');
    expect(steps[0].isReadOnly).toBe(true);
    expect(steps[1].isReadOnly).toBe(false);
  });

  it('steps respect task dependencies ordering', () => {
    const tracker = new TaskTracker();
    tracker.addTask({
      id: 't1',
      title: 'Setup DB',
      prompt: 'Create database schema',
      profile: 'db-admin',
      files: ['db/schema.sql'],
      dependencies: [],
    });
    tracker.addTask({
      id: 't2',
      title: 'Write API',
      prompt: 'Build REST API',
      profile: 'coder',
      files: ['src/api.ts'],
      dependencies: ['t1'],
    });

    // t2 is blocked because t1 is not done
    const task2 = tracker.getTask('t2')!;
    expect(task2.status).toBe('blocked');

    const getStepsForTask = (t: Task): StepDefinition[] => [
      { name: 'implement', profileId: t.profile, isReadOnly: false },
    ];

    const steps = getStepsForTask(task2);
    expect(steps[0].profileId).toBe('coder');

    // Complete t1 so t2 becomes ready
    tracker.claimTasks(1);
    tracker.startTask('t1', 'agent-1');
    tracker.submitForReview('t1', { schema: 'created' });
    tracker.completeTask('t1');

    const task2Updated = tracker.getTask('t2')!;
    expect(task2Updated.status).toBe('ready');
  });

  it('works with a real TaskTracker lifecycle and multiple tasks', () => {
    const tracker = new TaskTracker();

    // Add tasks with dependencies
    tracker.addTask({ id: 'a', title: 'A', prompt: 'Do A', profile: 'scout', files: [], dependencies: [] });
    tracker.addTask({ id: 'b', title: 'B', prompt: 'Do B', profile: 'coder', files: [], dependencies: ['a'] });
    tracker.addTask({ id: 'c', title: 'C', prompt: 'Do C', profile: 'coder', files: [], dependencies: ['a'] });

    // Initially only 'a' is ready
    expect(tracker.getReadyTasks().map((t) => t.id)).toEqual(['a']);

    // getStepsForTask for 'a' returns scout steps
    const getStepsForTask = (t: Task): StepDefinition[] => {
      if (t.profile === 'scout') {
        return [{ name: 'scout', profileId: 'scout', isReadOnly: true }];
      }
      return [
        { name: 'implement', profileId: t.profile, isReadOnly: false },
        { name: 'review', profileId: 'reviewer', isReadOnly: true },
      ];
    };

    const stepsA = getStepsForTask(tracker.getTask('a')!);
    expect(stepsA).toHaveLength(1);
    expect(stepsA[0].name).toBe('scout');

    // Complete 'a' through the full lifecycle
    tracker.claimTasks(1);
    tracker.startTask('a', 'agent-x');
    tracker.submitForReview('a', { report: 'done' });
    tracker.completeTask('a');

    // Now b and c should be ready
    const ready = tracker
      .getReadyTasks()
      .map((t) => t.id)
      .sort();
    expect(ready).toEqual(['b', 'c']);

    const stepsB = getStepsForTask(tracker.getTask('b')!);
    expect(stepsB).toHaveLength(2);
    expect(stepsB[1].profileId).toBe('reviewer');
  });
});

// ─── LanePoolOptions compilation ────────────────────────────────────────────

describe('LanePoolOptions', () => {
  it('compiles with required and optional fields', () => {
    const tracker = new TaskTracker();

    const options: LanePoolOptions = {
      maxConcurrentLanes: 4,
      profilesDirs: ['./profiles', '~/.config/engin/profiles'],
      sessionBaseDir: '/tmp/sessions',
      cwd: '/home/user/project',
      taskTracker: tracker,
      getStepsForTask: (_task: Task) => [
        { name: 'implement', profileId: 'coder', isReadOnly: false },
        { name: 'review', profileId: 'reviewer', isReadOnly: true },
      ],
    };

    expect(options.maxConcurrentLanes).toBe(4);
    expect(options.profilesDirs).toHaveLength(2);
    expect(options.apiKeys).toBeUndefined();
    expect(options.onStatus).toBeUndefined();
    expect(options.auditLog).toBeUndefined();
    expect(options.maxStepRetries).toBeUndefined();
    expect(options.taskTracker).toBe(tracker);
  });
});

import { afterEach, beforeEach, describe, expect, it } from 'bun:test';
import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { clearWorkflowCache, listWorkflows, loadWorkflow } from '../../src/core/workflow-loader.js';
import { useTempDir } from '../helpers/use-temp-dir.js';

// ─── Temp directory helper ──────────────────────────────────────────────────

const { getDir } = useTempDir();

let localWorkflowDir: string;
let globalWorkflowDir: string;
let savedXdg: string | undefined;

beforeEach(async () => {
  savedXdg = process.env.XDG_CONFIG_HOME;
  localWorkflowDir = join(getDir(), 'local', '.engin', 'workflows');
  globalWorkflowDir = join(getDir(), 'global', 'engin', 'workflows');
  await mkdir(localWorkflowDir, { recursive: true });
  await mkdir(globalWorkflowDir, { recursive: true });
  clearWorkflowCache();
});

afterEach(() => {
  if (savedXdg === undefined) {
    delete process.env.XDG_CONFIG_HOME;
  } else {
    process.env.XDG_CONFIG_HOME = savedXdg;
  }
});

/**
 * Helper: build a cwd whose resolveWorkflowsDirs returns our temp local + global dirs.
 * We set XDG_CONFIG_HOME so that the global dir maps to globalWorkflowDir.
 */
function makeCwd(): string {
  // cwd must be <getDir()>/local so that .engin/workflows = localWorkflowDir
  // XDG_CONFIG_HOME must be <getDir()>/global so that engin = globalWorkflowDir
  process.env.XDG_CONFIG_HOME = join(getDir(), 'global');
  return join(getDir(), 'local');
}

/**
 * Helper: create a directory-based workflow in the given workflows directory.
 * Structure: <workflowsDir>/<name>/main.ts
 */
async function createDirWorkflow(
  workflowsDir: string,
  name: string,
  content = "export async function run() { return 'ok'; }",
): Promise<void> {
  await mkdir(join(workflowsDir, name), { recursive: true });
  await writeFile(join(workflowsDir, name, 'main.ts'), content);
}

// ─── listWorkflows ──────────────────────────────────────────────────────────

describe('listWorkflows', () => {
  it('returns empty array when no dirs exist', async () => {
    const emptyCwd = join(getDir(), 'nowhere');
    await mkdir(emptyCwd, { recursive: true });
    process.env.XDG_CONFIG_HOME = join(getDir(), 'nowhere-global');
    const result = await listWorkflows(emptyCwd);
    expect(result).toEqual([]);
  });

  it('finds directories with main.ts in global dir with correct source label', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(globalWorkflowDir, 'alpha');
    await createDirWorkflow(globalWorkflowDir, 'bravo');
    await createDirWorkflow(globalWorkflowDir, 'charlie');

    const result = await listWorkflows(cwd);
    expect(result).toHaveLength(3);
    expect(result.map((r) => r.name)).toEqual(['alpha', 'bravo', 'charlie']);
    for (const entry of result) {
      expect(entry.source).toBe('global');
      expect(entry.path).toBe(join(globalWorkflowDir, entry.name, 'main.ts'));
    }
  });

  it('finds directories in local dir with source label local', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(localWorkflowDir, 'local-only');

    const result = await listWorkflows(cwd);
    expect(result).toHaveLength(1);
    expect(result[0].name).toBe('local-only');
    expect(result[0].source).toBe('local');
    expect(result[0].path).toBe(join(localWorkflowDir, 'local-only', 'main.ts'));
  });

  it('returns both local and global entries for same name, local first', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(localWorkflowDir, 'shared', "export async function run() { return 'local'; }");
    await createDirWorkflow(globalWorkflowDir, 'shared', "export async function run() { return 'global'; }");

    const result = await listWorkflows(cwd);
    expect(result).toHaveLength(2);

    // local first due to sort
    expect(result[0].name).toBe('shared');
    expect(result[0].source).toBe('local');
    expect(result[1].name).toBe('shared');
    expect(result[1].source).toBe('global');
  });

  it('ignores directories without main.ts', async () => {
    const cwd = makeCwd();
    // Create a directory with other.ts but NOT main.ts
    await mkdir(join(globalWorkflowDir, 'no-main'), { recursive: true });
    await writeFile(join(globalWorkflowDir, 'no-main', 'other.ts'), 'export function run() {}');
    // Create a valid workflow
    await createDirWorkflow(globalWorkflowDir, 'valid');

    const result = await listWorkflows(cwd);
    expect(result).toHaveLength(1);
    expect(result[0].name).toBe('valid');
  });

  it('ignores plain files in workflows dir', async () => {
    const cwd = makeCwd();
    // Create a flat file (not a directory)
    await writeFile(join(globalWorkflowDir, 'flat-file.ts'), 'export function run() {}');
    // Create a valid directory workflow
    await createDirWorkflow(globalWorkflowDir, 'valid');

    const result = await listWorkflows(cwd);
    expect(result).toHaveLength(1);
    expect(result[0].name).toBe('valid');
  });

  it('ignores hidden directories starting with .', async () => {
    const cwd = makeCwd();
    // Create a hidden directory with main.ts inside
    const hiddenDir = join(globalWorkflowDir, '.hidden');
    await mkdir(hiddenDir, { recursive: true });
    await writeFile(join(hiddenDir, 'main.ts'), 'export function run() {}');
    // Create a valid workflow
    await createDirWorkflow(globalWorkflowDir, 'visible');

    const result = await listWorkflows(cwd);
    expect(result).toHaveLength(1);
    expect(result[0].name).toBe('visible');
  });

  it('results are sorted by name then source (local before global for same name)', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(localWorkflowDir, 'beta');
    await createDirWorkflow(globalWorkflowDir, 'alpha');
    await createDirWorkflow(localWorkflowDir, 'alpha');

    const result = await listWorkflows(cwd);
    expect(result.map((r) => `${r.name}:${r.source}`)).toEqual(['alpha:local', 'alpha:global', 'beta:local']);
  });
});

// ─── loadWorkflow ───────────────────────────────────────────────────────────

describe('loadWorkflow', () => {
  it('throws with descriptive error when name not found', async () => {
    const cwd = makeCwd();
    await expect(loadWorkflow('nonexistent', cwd)).rejects.toThrow("Workflow 'nonexistent' not found.");
  });

  it('throws when module has no run export', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(globalWorkflowDir, 'bad-module', 'export const something = 42;');

    await expect(loadWorkflow('bad-module', cwd)).rejects.toThrow(
      "Workflow 'bad-module' does not export a 'run' function.",
    );
  });

  it('loads main.ts and returns its run function', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(
      globalWorkflowDir,
      'hello',
      "export async function run(taskPrompt, options) { return 'hello-result'; }",
    );

    const mod = await loadWorkflow('hello', cwd);
    expect(typeof mod.run).toBe('function');
    const result = await mod.run('test', { cwd: '/tmp', workDir: '/tmp/work' });
    expect(result).toBe('hello-result');
  });

  it('loads a module with default export', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(
      globalWorkflowDir,
      'default-export',
      "export default { async run(taskPrompt, options) { return 'default-result'; } };",
    );

    const mod = await loadWorkflow('default-export', cwd);
    expect(typeof mod.run).toBe('function');
    const result = await mod.run('test', { cwd: '/tmp', workDir: '/tmp/work' });
    expect(result).toBe('default-result');
  });

  it('prefers local workflow over global with same name', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(localWorkflowDir, 'override', "export async function run() { return 'local'; }");
    await createDirWorkflow(globalWorkflowDir, 'override', "export async function run() { return 'global'; }");

    const mod = await loadWorkflow('override', cwd);
    const result = await mod.run('', { cwd: '', workDir: '' });
    expect(result).toBe('local');
  });

  it('caches modules (call twice, same reference returned)', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(
      globalWorkflowDir,
      'cached',
      'let callCount = 0; export async function run() { return ++callCount; }',
    );

    const mod1 = await loadWorkflow('cached', cwd);
    const result1 = await mod1.run('', { cwd: '', workDir: '' });
    expect(result1).toBe(1);

    // Second load should return the same cached module — counter keeps incrementing
    const mod2 = await loadWorkflow('cached', cwd);
    const result2 = await mod2.run('', { cwd: '', workDir: '' });
    expect(result2).toBe(2);

    // Same object reference (cached)
    expect(mod1).toBe(mod2);
  });

  it('throws for path traversal with forward slash', async () => {
    const cwd = makeCwd();
    await expect(loadWorkflow('../etc/passwd', cwd)).rejects.toThrow(
      'Invalid workflow name: "../etc/passwd". Names must not contain path separators or "..".',
    );
  });

  it('throws for path traversal with backslash', async () => {
    const cwd = makeCwd();
    await expect(loadWorkflow('foo\\bar', cwd)).rejects.toThrow(
      'Invalid workflow name: "foo\\bar". Names must not contain path separators or "..".',
    );
  });

  it('throws for path traversal with double dot', async () => {
    const cwd = makeCwd();
    await expect(loadWorkflow('..', cwd)).rejects.toThrow(
      'Invalid workflow name: "..". Names must not contain path separators or "..".',
    );
  });
});

// ─── clearWorkflowCache ─────────────────────────────────────────────────────

describe('clearWorkflowCache', () => {
  it('cache clear does not break subsequent loads', async () => {
    const cwd = makeCwd();
    await createDirWorkflow(globalWorkflowDir, 'cache-clear', 'export async function run() { return 42; }');

    // First load populates the cache
    const mod1 = await loadWorkflow('cache-clear', cwd);
    expect(typeof mod1.run).toBe('function');

    // Clear the cache
    clearWorkflowCache();

    // Next load still works (re-resolves via the same path)
    const mod2 = await loadWorkflow('cache-clear', cwd);
    expect(typeof mod2.run).toBe('function');
    const result = await mod2.run('', { cwd: '', workDir: '' });
    expect(result).toBe(42);
  });
});

